private bool GetReplaceWord(string pre, string word, string post, out string result)
{
    if (GetReplaceWordExact(pre, word, post, out result))
    {
        return true;
    }

    // Try again with first letter lower case (e.g. sentence start), restoring upper case on the result
    if (word.Length > 1 && char.IsUpper(word[0]) && !char.IsUpper(word[1]))
    {
        var lowerWord = char.ToLowerInvariant(word[0]) + word.Substring(1);
        if (GetReplaceWordExact(pre, lowerWord, post, out var lowerResult) && lowerResult.Length > pre.Length)
        {
            var idx = pre.Length;
            result = lowerResult.Substring(0, idx) + char.ToUpperInvariant(lowerResult[idx]) + lowerResult.Substring(idx + 1);
            return true;
        }
    }

    result = string.Empty;
    return false;
}

